require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/session.php';require_once __DIR__.'/../includes/functions.php';if(!is_attendee_logged_in())redirect('../index.php');$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){if(!verify_csrf_token($_POST['csrf_token']??''))$error='Security token expired.';else{$data=['full_name'=>trim($_POST['full_name']??''),'email'=>trim($_POST['email']??''),'phone'=>trim($_POST['phone']??''),'course'=>trim($_POST['course']??''),'year_level'=>trim($_POST['year_level']??''),'section'=>trim($_POST['section']??'')];$reason=trim($_POST['reason']??'');if($data['full_name']==='')$error='Complete name is required.';elseif($data['email']!==''&&!filter_var($data['email'],FILTER_VALIDATE_EMAIL))$error='Invalid email address.';else{$ok=pg_query_params($conn,'INSERT INTO student_information_requests(attendee_id,requested_data,reason) VALUES($1,$2::jsonb,$3)',[$_SESSION['attendee_id'],json_encode($data),$reason]);if($ok)redirect('requests.php?saved=1');$error='Request could not be submitted.';}}}
$profile=pg_fetch_assoc(pg_query_params($conn,'SELECT * FROM attendees WHERE id=$1',[$_SESSION['attendee_id']]));$rows=pg_query_params($conn,'SELECT r.*,a.full_name reviewer_name FROM student_information_requests r LEFT JOIN admins a ON a.id=r.reviewed_by WHERE r.attendee_id=$1 ORDER BY r.created_at DESC',[$_SESSION['attendee_id']]);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Requests · <?=h(site_name())?></title><link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css"><link rel="stylesheet" href="../assets/css/feedback.css"></head><body class="feedback-ballot vms-participant" style="--feedback-bg:url('../<?=h(site_background())?>')"><div class="participant-wrapper"><div class="participant-container"><header class="participant-topbar"><div class="participant-info"><span class="participant-badge"><i class="fas fa-user-pen"></i> My Information Requests</span></div><a class="btn secondary" href="dashboard.php"><i class="fas fa-arrow-left"></i> My Events</a></header><section class="participant-banner"><h1>Request an Information Update</h1><p>Your current record changes only after an administrator approves the request.</p></section><?php if(isset($_GET['saved'])):?><div class="participant-alert" style="background:#dcfce7;color:#166534">Request submitted for review.</div><?php endif;?><?php if($error):?><div class="participant-alert error"><?=h($error)?></div><?php endif;?><div class="position-card"><form method="post" class="form-grid"><?=csrf_field()?><div class="field"><label>Complete name</label><input name="full_name" required value="<?=h($profile['full_name'])?>"></div><div class="field"><label>Email</label><input type="email" name="email" value="<?=h($profile['email']??'')?>"></div><div class="field"><label>Phone</label><input name="phone" value="<?=h($profile['phone']??'')?>"></div><div class="field"><label>Course</label><input name="course" value="<?=h($profile['course']??'')?>"></div><div class="field"><label>Year level</label><input name="year_level" value="<?=h($profile['year_level']??'')?>"></div><div class="field"><label>Section</label><input name="section" value="<?=h($profile['section']??'')?>"></div><div class="field full"><label>Reason for change</label><textarea name="reason"></textarea></div><div class="field full"><button class="btn">Submit Request</button></div></form></div><div class="position-card"><h3>Request history</h3><div class="table-wrap"><table><thead><tr><th>Submitted</th><th>Status</th><th>Reviewed By</th><th>Remarks</th></tr></thead><tbody><?php if($rows):while($r=pg_fetch_assoc($rows)):?><tr><td><?=h(date('M j, Y g:i A',strtotime($r['created_at'])))?></td><td><span class="badge <?=h($r['status'])?>"><?=h(ucfirst($r['status']))?></span></td><td><?=h($r['reviewer_name']?:'—')?></td><td><?=h($r['reviewer_notes']?:'—')?></td></tr><?php endwhile;endif;if(!$rows||pg_num_rows($rows)===0):?><tr><td colspan="4" class="empty">No requests yet.</td></tr><?php endif;?></tbody></table></div></div></div></div></body></html>
